import { useApi } from '@shopify/ui-extensions-react/admin';

function Component() {
  const { data } = useApi();
  const productId = data.selected[0].id;
  // use productId numa query GraphQL pra buscar mais detalhes
}

const response = await fetch("shopify:admin/api/graphql.json", {
  method: "POST",
  body: JSON.stringify({
    query: `query($id: ID!) {
      product(id: $id) { metafield(namespace: "custom", key: "material") { value } }
    }`,
    variables: { id: productId }
  })
});
